isd = lambda s: s.isdigit()
def runs(tk, lo, hi):
    out=[]; cur=[]
    for i in range(lo,hi):
        if isd(tk[i]): cur.append(i)
        else:
            if cur: out.append(cur); cur=[]
    if cur: out.append(cur)
